 if(!Array.isArray(s.agents)||s.agents.length>100||s.agents.some(a=>!id(a.id)||(a.color!==undefined&&!color(a.color))||!heroRoster.some(h=>h.id===a.hero)||!coord(a.position)||!['ready','watch','patrol'].includes(a.order)||!number(a.hp,0,8)||!number(a.mental,0,10)||!number(a.energy,0,100)))throw Error('Agents invalides');
 if(!Array.isArray(s.vehicles)||s.vehicles.length>100||s.vehicles.some(v=>!id(v.id)||!['car','bike'].includes(v.kind)||!coord(v.position)||!number(v.heading,0,360)))throw Error('Véhicules invalides');
 if(!Array.isArray(s.zones)||s.zones.length>100||s.zones.some(z=>!id(z.id)||!id(z.name)||!color(z.color)||!['watch','patrol'].includes(z.order)||!Array.isArray(z.ring)||z.ring.length<4||z.ring.length>1500||!z.ring.every(coord)||z.ring[0][0]!==z.ring.at(-1)![0]||z.ring[0][1]!==z.ring.at(-1)![1]))throw Error('Zones invalides');
