 if(s.zones.some(z=>z.agent!==undefined&&!s.agents.some(a=>a.id===z.agent))||s.agents.some(a=>a.zone!==undefined&&!s.zones.some(z=>z.id===a.zone)))throw Error('Affectation invalide');
