 for(const a of [...s.agents,...s.vehicles])if(a.journey&&(!Array.isArray(a.journey.path)||a.journey.path.length<2||a.journey.path.length>20000||!a.journey.path.every(coord)||!Number.isInteger(a.journey.next)||a.journey.next<1||a.journey.next>=a.journey.path.length||typeof a.journey.destination!=='string'||a.journey.destination.length>120))throw Error('Trajet invalide');
