 function scheduleDuty(a:Agent){clearTimeout(dutyTimers.get(a.id));dutyTimers.set(a.id,setTimeout(()=>runDuty(a.id),1200));}
 function scheduleResume(a:Agent){clearTimeout(dutyTimers.get(a.id));dutyTimers.set(a.id,setTimeout(()=>{if(!a.resumeIdle||a.journey)return;const pref=a.idle||{order:'ready' as const};delete a.resumeIdle;setDuty(a,pref.order,pref.zone);},1200));}
 function runDuty(id:string){const a=scene.agents.find(a=>a.id===id);if(!a||!a.duty||a.journey)return;const z=scene.zones.find(z=>z.id===a.zone);if(a.order==='ready'){const hq=getPoints().filter(p=>p.type==='hq').sort((p,q)=>roadDistance(a.position,[p.lng,p.lat])-roadDistance(a.position,[q.lng,q.lat]))[0];if(hq){if(a.point===hq.id){syncSheet();return;}delete a.point;travel.send(a.id,[hq.lng,hq.lat],hq.name,undefined,hq.id);occupants();}else status('Place un point QG pour permettre le retour du héros.');syncSheet();return;}if(!z){status('Choisis un secteur dans la fiche du héros.');return;}const network=travel.network(),sector=network.sector(z.ring,z.tolerance??12),loop=sector.patrolPath(a.position);if(loop.length<3){status('Aucune rue accessible dans ce secteur. Augmente sa marge ou charge les rues alentour.');return;}const approach=network.route(a.position,loop[0]);if(approach.length<2){status('Aucun parcours routier continu vers ce secteur.');return;}approach[approach.length-1]=loop[0];const atStart=roadDistance(a.position,loop[0])<1,path=atStart?loop:[...approach,...loop.slice(1)],loopStart=atStart?0:approach.length-1;travel.follow(a.id,path,z.name,undefined,loopStart);syncSheet();}
 function setDuty(a:Agent,order:Agent['order'],zone?:string){a.idle={order:order==='ready'?'ready':'watch',zone:order==='ready'?undefined:zone||undefined};delete a.resumeIdle;moveActor=undefined;if(order==='patrol')order='watch';cancelDuty(a.id);for(const z of scene.zones)if(z.agent===a.id)delete z.agent;a.order=order;a.duty=true;if(!(order==='ready'&&atHQ(a)))delete a.point;delete a.zone;const z=scene.zones.find(z=>z.id===zone);if(order!=='ready'&&z){if(z.agent){const previous=scene.agents.find(x=>x.id===z.agent);if(previous){cancelDuty(previous.id);previous.duty=false;delete previous.zone;previous.order='ready';previous.idle={order:'ready'};}}z.agent=a.id;z.order=order;z.color=scene.zoneColors![order];a.zone=z.id;}renderActors();renderZones();zoneEditor();syncSheet();changed();runDuty(a.id);}
 function dispatch(position:Coord,label='Destination',point?:string){const a=scene.agents.find(a=>a.id===moveActor);const actor=a||scene.vehicles.find(v=>v.id===moveActor);if(!actor)return false;moveActor=undefined;cancelDuty(actor.id);if(a){a.idle??={order:a.order==='ready'?'ready':'watch',zone:a.zone};delete a.point;a.duty=false;a.order='ready';a.resumeIdle=true;renderZones();}const sent=travel.send(actor.id,position,label,undefined,point);if(!sent&&a)scheduleResume(a);renderActors();vehicleEditor();syncSheet();return true;}
 function syncEffects(){for(const input of ambiance.querySelectorAll<HTMLInputElement>('[data-effect]')){const key=input.dataset.effect as keyof Ambience;if(input.type==='checkbox')input.checked=scene.ambience[key] as boolean;else input.value=String(scene.ambience[key]);const out=ambiance.querySelector(`[data-effect-out="${key}"]`);if(out)out.textContent=String(scene.ambience[key]);}}
 function effects(){const a=scene.ambience;viewport.style.setProperty('--point-glow','0px');viewport.classList.remove('pulse-alerts');viewport.classList.toggle('token-shadows',a.shadows);$('map').style.filter=`contrast(${a.contrast}) saturate(${a.saturation})`;map.setLight({anchor:'map',color:a.lightColor,intensity:a.light,position:[1.5,a.azimuth,45]});if(map.getLayer('scene-zone-fill'))map.setPaintProperty('scene-zone-fill','fill-opacity',a.zoneOpacity);syncEffects();}
 function windowLayout(){
  const v=scene.window,w=Math.min(v.width,viewport.clientWidth-20),scale=w/HERO_SHEET_WIDTH,height=Math.min(v.height??w*920/520,viewport.clientHeight-(scene.agents.length?207:24));
  floating.querySelector<HTMLElement>('.hero-window-canvas')!.style.height=`${height/scale}px`;$<HTMLIFrameElement>('hero-frame').style.height=`${(height-18)/scale-48}px`;
  floating.style.width=`${w}px`;floating.style.height=`${height}px`;floating.style.left=`${Math.max(8,Math.min(v.x*viewport.clientWidth,viewport.clientWidth-w-8))}px`;floating.style.top=`${Math.max(8,Math.min(v.y*viewport.clientHeight,viewport.clientHeight-height-(scene.agents.length?207:8)))}px`;floating.querySelector<HTMLElement>('.hero-window-canvas')!.style.transform=`scale(${scale})`;viewport.dispatchEvent(new Event('map-layout'));
 }
 function selectionUI(){for(const v of scene.vehicles){const el=markers.find(m=>m.getElement().dataset.actor===v.id)?.getElement();el?.classList.toggle('is-selected',v.id===selectedVehicle);el?.setAttribute('aria-pressed',String(v.id===selectedVehicle));}for(const a of scene.agents){const el=markers.find(m=>m.getElement().dataset.actor===a.id)?.getElement();if(!el)continue;const selected=scene.window.open&&scene.window.agent===a.id;el.classList.toggle('is-selected',selected);el.setAttribute('aria-pressed',String(selected));el.style.setProperty('--point',a.color||'#78dcde');}}
 function windowUI(){dock.refresh();selectionUI();syncFocus();const a=scene.agents.find(a=>a.id===scene.window.agent);floating.hidden=!scene.window.open||!a;windowLayout();if(!a){frameKey='';return;}const name=heroRoster.find(h=>h.id===a.hero)!.name;$('hero-window-title').textContent=name;floating.setAttribute('aria-label',`Fiche de ${name}`);if(frameKey!==a.id){frameKey=a.id;$<HTMLIFrameElement>('hero-frame').src=heroSheetURL(context()!);}}
 function openAgent(id:string){moveActor=undefined;if(juice.select(`hero:${id}`))return;juice.trigger(`hero:${id}`,'click');selectedVehicle=undefined;selectedZone=undefined;zoneEditor();scene.window={...scene.window,agent:id,open:true};windowUI();syncSheet();changed();}
 function token(position:Coord,el:HTMLElement,ground=false){const m=new Marker({element:el,draggable:!drawing,anchor:ground?'center':'bottom',pitchAlignment:ground?'map':'viewport',rotationAlignment:ground?'map':'viewport'}).setLngLat(position).addTo(map);markers.push(m);return m;}
 function renderActors(){markers.forEach(m=>m.remove());markers=[];
  for(const a of scene.agents){const h=heroRoster.find(h=>h.id===a.hero)!;const el=document.createElement('button');el.className='agent-token';el.setAttribute('aria-label',`Fiche de ${h.name}`);el.dataset.actor=a.id;el.style.setProperty('--point',a.color||'#78dcde');el.innerHTML=`<span class="token-ground"></span><span class="token-stem"></span><span class="token-portrait"><img src="${heroAsset(a.hero,'portrait','dossier')}" alt=""><span class="token-order">${icon(activityForOrder(a.order).icon)}</span></span><span class="token-caption">${esc(h.name)}</span>`;el.onclick=e=>{e.stopPropagation();if(!drawing&&!suppressClick)openAgent(a.id);};const m=token(a.position,el);m.on('dragstart',()=>{suppressClick=true;cancelDuty(a.id);a.duty=false;delete a.point;occupants();});m.on('dragend',()=>{const c=m.getLngLat();a.position=[c.lng,c.lat];setTimeout(()=>suppressClick=false,100);changed();});}
  for(const v of scene.vehicles){const el=document.createElement('button');el.className='vehicle-token';el.dataset.actor=v.id;el.setAttribute('aria-label',v.kind==='car'?'Voiture':'Moto');el.innerHTML=v.kind==='car'?car:icon('motorbike');el.onclick=e=>{e.stopPropagation();if(juice.select(`vehicle:${v.id}`))return;juice.trigger(`vehicle:${v.id}`,'click');moveActor=undefined;selectedVehicle=v.id;scene.window.open=false;windowUI();vehicleEditor();};const m=token(v.position,el,true);m.setRotation(v.heading);m.on('dragstart',()=>{cancelDuty(v.id);});m.on('dragend',()=>{const c=m.getLngLat();v.position=[c.lng,c.lat];changed();});}
  perspective();lists();selectionUI();occupants();syncFocus();dock.refresh();
 }
 function perspective(){for(const el of viewport.querySelectorAll<HTMLElement>('.token-ground')){el.style.transform=`rotateX(${map.getPitch()}deg) rotateZ(${-map.getBearing()}deg)`;}}
 function lists(){
  $('agent-list').innerHTML=scene.agents.map(a=>{const h=heroRoster.find(h=>h.id===a.hero)!;return `<div class="agent-options"><div class="scene-row"><button data-agent="${a.id}"><img src="${heroAsset(a.hero,'portrait','dossier')}" alt=""><span>${esc(h.name)}<small>${a.order!=='ready'?'Surveillance':'Disponible'}</small></span></button><button data-center-agent="${a.id}" aria-label="Centrer sur ${esc(h.name)}">${icon('target')}</button><button data-remove-agent="${a.id}" aria-label="Retirer ${esc(h.name)}">${icon('x')}</button></div><label class="color-row hero-token-color">Halo de ${esc(h.name)}<input type="color" data-agent-color="${a.id}" aria-label="Couleur du halo de ${esc(h.name)}" value="${a.color||'#78dcde'}"></label></div>`;}).join('');
  $('vehicle-list').innerHTML=scene.vehicles.map(v=>`<div class="scene-row"><button data-vehicle="${v.id}">${icon('route')}${v.kind==='car'?'Voiture':'Moto'}</button><button data-center-vehicle="${v.id}" aria-label="Centrer sur le véhicule">${icon('target')}</button><button data-remove-vehicle="${v.id}" aria-label="Retirer le véhicule">${icon('x')}</button></div>`).join('');
  $('zone-list').innerHTML=scene.zones.map(z=>`<div class="sector-row"><button class="zone-row" data-zone="${z.id}" style="--zone:${z.color}">${icon(activityForOrder(z.order).icon)}<span>${esc(z.name)}${zonePortrait(z)}<small>Surveillance</small></span></button><button data-center-zone="${z.id}" aria-label="Placer ${esc(z.name)} au centre">${icon('target')}</button></div>`).join('');
 }
 function vehicleEditor(){const v=scene.vehicles.find(v=>v.id===selectedVehicle),el=$('vehicle-editor');el.hidden=!v;if(v)el.innerHTML=`<button id="vehicle-move" aria-pressed="${moveActor===v.id}">${icon('route')}Déplacer le véhicule</button>${v.journey?`<button id="vehicle-cancel">${icon('x')}Annuler le trajet…</button>`:''}<label class="range">Orientation<output>${v.heading}°</output><input id="vehicle-heading" type="range" min="0" max="360" step="5" value="${v.heading}"></label>`;}
 function zonePortrait(z:Zone){const a=scene.agents.find(a=>a.id===z.agent);return a?`<img class="zone-portrait" src="${heroAsset(a.hero,'portrait','dossier')}" alt="${esc(heroRoster.find(h=>h.id===a.hero)!.name)}">`:'';}
 function zoneCenter(z:Zone):Coord{return z.ring.slice(0,-1).reduce((sum,p)=>[sum[0]+p[0]/(z.ring.length-1),sum[1]+p[1]/(z.ring.length-1)] as Coord,[0,0] as Coord);}
 function openZone(id:string){if(juice.select(`zone:${id}`))return;juice.trigger(`zone:${id}`,'click');selectedZone=id;selectedPoint=undefined;$('selection').hidden=true;zoneEditor();syncFocus();}
 function zoneEditor(){const z=scene.zones.find(z=>z.id===selectedZone),el=$('zone-editor');el.hidden=!z;if(!z)return;el.innerHTML=`<div class="selection-head"><b>${icon(activityForOrder(z.order).icon)} Secteur ${zonePortrait(z)}</b><button id="close-zone" aria-label="Fermer le secteur">${icon('x')}</button></div><label>Nom<input id="edit-zone-name" maxlength="80" value="${esc(z.name)}"></label><label>Assigner à<select id="zone-agent"><option value="">Personne</option>${scene.agents.map(a=>`<option value="${a.id}" ${a.id===z.agent?'selected':''}>${esc(heroRoster.find(h=>h.id===a.hero)!.name)}</option>`).join('')}</select></label><label class="range">Marge autour du tracé<output>${z.tolerance??12} m</output><input id="zone-tolerance" type="range" min="0" max="80" step="5" value="${z.tolerance??12}"></label><p class="hint">Le trajet reste dans cette marge et parcourt les rues et ruelles connectées du secteur.</p><button data-center-zone="${z.id}">${icon('target')}Placer au centre</button><button id="remove-zone" class="danger">${icon('x')}Supprimer la zone</button>`;placeMapPopover(map,el,zoneCenter(z),z.ring);}

 function assign(z:Zone){z.color=scene.zoneColors![z.order];const a=scene.agents.find(a=>a.id===z.agent);for(const other of scene.agents)if(other.zone===z.id&&other.id!==a?.id){cancelDuty(other.id);other.duty=false;delete other.zone;other.order='ready';other.idle={order:'ready'};}if(a)setDuty(a,z.order,z.id);else{renderActors();renderZones();zoneEditor();syncSheet();changed();}}

 function renderZones(){
  const data:FeatureCollection={type:'FeatureCollection',features:scene.zones.map(z=>({type:'Feature',properties:{id:z.id,color:z.color},geometry:{type:'Polygon',coordinates:[z.ring]}}))};
  (map.getSource('scene-zones') as GeoJSONSource)?.setData(data);zoneMarkers.forEach(m=>m.remove());zoneMarkers=[];
  for(const z of scene.zones){const center=zoneCenter(z);const el=document.createElement('button');el.className='zone-label';el.dataset.zone=z.id;el.style.setProperty('--zone',z.color);el.innerHTML=`<span>${esc(z.name)}</span>${zonePortrait(z)}`;el.onclick=e=>{e.stopPropagation();openZone(z.id);};zoneMarkers.push(new Marker({element:el,offset:[0,-30]}).setLngLat(center).addTo(map));}lists();syncSheet();juice.refresh();
 }
 function addAgent(position:Coord){if(scene.agents.length>=100)return;const hero=$<HTMLSelectElement>('map-hero').value;const a:Agent={id:crypto.randomUUID(),hero,position,order:'ready',color:'#78dcde',hp:6,mental:8,energy:75};a.duty=true;a.idle={order:'ready'};scene.agents.push(a);scheduleDuty(a);renderActors();zoneEditor();openAgent(a.id);status(`${heroRoster.find(h=>h.id===hero)!.name} placé. Glisse son token pour le déplacer.`);changed();}
 function addVehicle(position:Coord){if(scene.vehicles.length>=100)return;const v:Vehicle={id:crypto.randomUUID(),kind:$<HTMLSelectElement>('vehicle-kind').value as Vehicle['kind'],position,heading:0};scene.vehicles.push(v);moveActor=undefined;selectedVehicle=v.id;scene.window.open=false;windowUI();renderActors();vehicleEditor();changed();}
 const center=():Coord=>{const c=map.getCenter();return [c.lng,c.lat];};
 function stopDrawing(){drawing=false;stroke=[];screenStroke=[];path.setAttribute('d','');svg.classList.remove('drawing');viewport.classList.remove('drawing-zone');map.dragPan.enable();map.touchZoomRotate.enable();if(map.getContainer().dataset.cameraLocked==='true')map.touchZoomRotate.disableRotation();map.scrollZoom.enable();markers.forEach(m=>m.setDraggable(true));$('draw-zone').setAttribute('aria-pressed','false');$('map-pencil').setAttribute('aria-pressed','false');$('cancel-pencil').hidden=true;}
 function startDrawing(){if(drawing){stopDrawing();return;}selectedZone=undefined;zoneEditor();$('selection').hidden=true;scene.window.open=false;windowUI();mode=undefined;drawing=true;svg.classList.add('drawing');viewport.classList.add('drawing-zone');map.dragPan.disable();map.touchZoomRotate.disable();map.scrollZoom.disable();markers.forEach(m=>m.setDraggable(false));$('draw-zone').setAttribute('aria-pressed','true');$('map-pencil').setAttribute('aria-pressed','true');$('cancel-pencil').hidden=false;status('Crayon actif · encercle un lieu. Échap pour annuler.');}
 function drawPoint(e:PointerEvent){const r=svg.getBoundingClientRect(),p:Coord=[e.clientX-r.left,e.clientY-r.top],last=screenStroke.at(-1);if(last&&Math.hypot(last[0]-p[0],last[1]-p[1])<4)return;if(stroke.length>=1499)return;const c=map.unproject(p);stroke.push([c.lng,c.lat]);screenStroke.push(p);path.setAttribute('d',screenStroke.map((p,i)=>`${i?'L':'M'}${p[0]} ${p[1]}`).join(' '));path.setAttribute('stroke',$<HTMLInputElement>('zone-color').value);}
 let activePointer:number|undefined;
 svg.addEventListener('pointerdown',e=>{if(!drawing||activePointer!==undefined||e.button!==0)return;e.preventDefault();activePointer=e.pointerId;svg.setPointerCapture(e.pointerId);stroke=[];screenStroke=[];drawPoint(e);});
 svg.addEventListener('pointermove',e=>{if(e.pointerId===activePointer)drawPoint(e);});
 svg.addEventListener('pointerup',e=>{if(e.pointerId!==activePointer)return;drawPoint(e);activePointer=undefined;svg.releasePointerCapture(e.pointerId);const area=Math.abs(screenStroke.reduce((sum,p,i)=>{const q=screenStroke[(i+1)%screenStroke.length];return sum+p[0]*q[1]-q[0]*p[1];},0))/2;
  if(stroke.length<4||area<100){stroke=[];screenStroke=[];path.setAttribute('d','');status('Trace un contour plus grand pour créer une zone.');return;}
  if(scene.zones.length>=100){stopDrawing();status('Limite de 100 zones atteinte.');return;}
  const clean=pencilRing(screenStroke);if(clean.length<4){stopDrawing();status('Contour trop petit. Recommence le secteur.');return;}
  const z:Zone={id:crypto.randomUUID(),name:$<HTMLInputElement>('zone-name').value.trim()||`Secteur ${scene.zones.length+1}`,ring:clean.map(p=>{const c=map.unproject(p);return [c.lng,c.lat] as Coord;}),color:scene.zoneColors!.watch,order:'watch'};scene.zones.push(z);selectedZone=z.id;suppressClick=true;setTimeout(()=>suppressClick=false,100);stopDrawing();renderZones();zoneEditor();changed();status(`${z.name} tracé · assigne un héros dans la fenêtre du secteur.`);
 });
 svg.addEventListener('pointercancel',()=>{activePointer=undefined;stopDrawing();});
 $('draw-zone').onclick=startDrawing;$('map-pencil').onclick=startDrawing;$('cancel-pencil').onclick=stopDrawing;
 $('add-agent').onclick=()=>addAgent(center());$('add-vehicle').onclick=()=>addVehicle(center());
 $('place-agent').onclick=()=>{stopDrawing();mode=mode==='agent'?undefined:'agent';status(mode?'Touche la carte pour placer le héros.':'Placement annulé.');};$('place-vehicle').onclick=()=>{stopDrawing();mode=mode==='vehicle'?undefined:'vehicle';status(mode?'Touche la carte pour placer le véhicule.':'Placement annulé.');};
 map.on('click',e=>{if(drawing||suppressClick||buildings.picking()||buildings.handled(e.originalEvent))return;const p:Coord=[e.lngLat.lng,e.lngLat.lat];if(mode){mode==='agent'?addAgent(p):addVehicle(p);mode=undefined;return;}if(juice.active())return;if(dispatch(p)){suppressClick=true;setTimeout(()=>suppressClick=false,100);}});

 function sceneClick(e:Event){const b=(e.target as HTMLElement).closest<HTMLButtonElement>('button');if(!b)return;
  if(b.dataset.agent)openAgent(b.dataset.agent);
  if(b.dataset.vehicle){moveActor=undefined;selectedVehicle=b.dataset.vehicle;scene.window.open=false;windowUI();vehicleEditor();changed();}
  if(b.dataset.zone)openZone(b.dataset.zone);
  if(b.dataset.centerZone){const z=scene.zones.find(z=>z.id===b.dataset.centerZone);if(z)centerTarget(`zone:${z.id}`,zoneCenter(z));}
  if(b.id==='vehicle-move'){moveActor=moveActor===selectedVehicle?undefined:selectedVehicle;vehicleEditor();status(moveActor?'Choisis une destination sur la carte. Échap annule.':'Déplacement annulé.');}if(b.id==='vehicle-cancel'&&selectedVehicle&&confirm('Annuler le trajet de ce véhicule ?')){cancelDuty(selectedVehicle);moveActor=undefined;vehicleEditor();changed();}
  if(b.id==='close-zone'){selectedZone=undefined;zoneEditor();syncFocus();}
  if(b.dataset.centerAgent){const a=scene.agents.find(a=>a.id===b.dataset.centerAgent);if(a)centerTarget(`hero:${a.id}`,a.position);}if(b.dataset.centerVehicle){const v=scene.vehicles.find(v=>v.id===b.dataset.centerVehicle);if(v)centerTarget(`vehicle:${v.id}`,v.position);}
  if(b.dataset.removeAgent){const id=b.dataset.removeAgent;cancelDuty(id);scene.agents=scene.agents.filter(a=>a.id!==id);for(const z of scene.zones)if(z.agent===id)delete z.agent;if(scene.window.agent===id){scene.window.open=false;delete scene.window.agent;}renderActors();renderZones();zoneEditor();windowUI();changed();}
  if(b.dataset.removeVehicle){cancelDuty(b.dataset.removeVehicle);scene.vehicles=scene.vehicles.filter(v=>v.id!==b.dataset.removeVehicle);renderActors();vehicleEditor();changed();}
  if(b.id==='remove-zone'){const z=scene.zones.find(z=>z.id===selectedZone);if(!z)return;delete z.agent;assign(z);scene.zones=scene.zones.filter(z=>z.id!==selectedZone);selectedZone=undefined;renderZones();zoneEditor();changed();}
 }
 tools.addEventListener('click',sceneClick);zonePanel.addEventListener('click',sceneClick);
 tools.addEventListener('input',e=>{const colorInput=e.target as HTMLInputElement;if(colorInput.id==='travel-speed'){scene.travelSpeed=Number(colorInput.value);$('travel-speed-out').textContent=`×${scene.travelSpeed}`;changed();return;}if(colorInput.dataset.agentColor){const a=scene.agents.find(a=>a.id===colorInput.dataset.agentColor);if(a){a.color=colorInput.value;selectionUI();changed();}return;}const order=colorInput.dataset.zoneColor as 'watch'|'patrol'|undefined;if(order){scene.zoneColors![order]=colorInput.value;for(const z of scene.zones)if(z.order===order)z.color=colorInput.value;renderZones();zoneEditor();changed();return;}const input=e.target as HTMLInputElement,z=scene.zones.find(z=>z.id===selectedZone);if(input.id==='vehicle-heading'){const v=scene.vehicles.find(v=>v.id===selectedVehicle);if(v){v.heading=Number(input.value);renderActors();$('vehicle-editor').querySelector('output')!.textContent=`${v.heading}°`;changed();}}if(z&&input.id==='edit-zone-color'){z.color=input.value;renderZones();changed();}});
 zonePanel.addEventListener('change',e=>{const input=e.target as HTMLInputElement,z=scene.zones.find(z=>z.id===selectedZone);if(!z)return;if(input.id==='edit-zone-name'){z.name=input.value.trim()||z.name;renderZones();changed();}if(input.id==='zone-agent'){z.agent=input.value||undefined;assign(z);}if(input.id==='zone-tolerance'){z.tolerance=Number(input.value);assign(z);}});
 ambiance.addEventListener('input',e=>{const input=e.target as HTMLInputElement,key=input.dataset.effect as keyof Ambience;if(!key)return;(scene.ambience as unknown as Record<string,unknown>)[key]=input.type==='checkbox'?input.checked:input.type==='color'?input.value:Number(input.value);effects();changed();});
 ambiance.addEventListener('click',e=>{const mood=(e.target as HTMLElement).closest<HTMLElement>('[data-mood]')?.dataset.mood;if(!mood)return;scene.ambience={...scene.ambience,...defaultAmbience,...(mood==='night'?{light:.25,lightColor:'#a4bce8',azimuth:280,contrast:1.15,saturation:.85,glow:.7}:mood==='warm'?{light:.65,lightColor:'#ffe4bc',azimuth:120,contrast:1.05,saturation:1.15,glow:.3}:{})};effects();changed();});
 $('hero-center').onclick=()=>{const a=scene.agents.find(a=>a.id===scene.window.agent);if(a)centerTarget(`hero:${a.id}`,a.position);};
 $('hero-window-close').onclick=()=>{moveActor=undefined;scene.window.open=false;windowUI();changed();};$('hero-window-smaller').onclick=()=>{scene.window.width=Math.max(220,scene.window.width-40);windowLayout();changed();};$('hero-window-larger').onclick=()=>{scene.window.width=Math.min(640,scene.window.width+40);windowLayout();changed();};
 function manipulate(handle:HTMLElement,resize:boolean){let start:{pointer:number;x:number;y:number;left:number;top:number;width:number;height:number}|undefined;handle.addEventListener('pointerdown',e=>{if(e.button!==0)return;handle.setPointerCapture(e.pointerId);start={pointer:e.pointerId,x:e.clientX,y:e.clientY,left:parseFloat(floating.style.left),top:parseFloat(floating.style.top),width:parseFloat(floating.style.width),height:parseFloat(floating.style.height)};e.preventDefault();});handle.addEventListener('pointermove',e=>{if(!start||e.pointerId!==start.pointer)return;if(resize){scene.window.width=Math.max(220,Math.min(640,start.width+e.clientX-start.x));scene.window.height=Math.max(180,Math.min(1200,start.height+e.clientY-start.y));}else {const w=floating.offsetWidth,h=floating.offsetHeight;scene.window.x=Math.max(8,Math.min(viewport.clientWidth-w-8,start.left+e.clientX-start.x))/viewport.clientWidth;scene.window.y=Math.max(8,Math.min(viewport.clientHeight-h-8,start.top+e.clientY-start.y))/viewport.clientHeight;}windowLayout();});const end=(e:PointerEvent)=>{if(start&&e.pointerId===start.pointer){start=undefined;changed();}};handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',end);}
 manipulate($('hero-window-drag'),false);manipulate($('hero-window-resize'),true);
 window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(moveActor){moveActor=undefined;syncSheet();vehicleEditor();status('Choix de destination annulé.');return;}if(drawing){activePointer=undefined;stopDrawing();}else if(scene.window.open){scene.window.open=false;windowUI();changed();}else {selectedZone=undefined;zoneEditor();}mode=undefined;}});
 window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==$<HTMLIFrameElement>('hero-frame').contentWindow)return;if(e.data?.type==='hero-map-duty'){const a=scene.agents.find(a=>a.id===e.data.agent);if(a&&['ready','watch'].includes(e.data.order))setDuty(a,e.data.order,typeof e.data.zone==='string'?e.data.zone:undefined);return;}if(e.data?.type==='hero-map-ready'){const a=scene.agents.find(a=>a.id===e.data.agent);if(a&&a.speed===undefined&&typeof e.data.speed==='number'&&e.data.speed>=1&&e.data.speed<=100){a.speed=e.data.speed;changed();}syncSheet();return;}if(e.data?.type==='hero-map-move'){const a=scene.agents.find(a=>a.id===e.data.agent);if(a){moveActor=moveActor===a.id?undefined:a.id;syncSheet();status(moveActor?'Choisis une destination sur la carte. Échap annule.':'Choix de destination annulé.');}return;}if(e.data?.type==='hero-map-cancel'){const a=scene.agents.find(a=>a.id===e.data.agent);if(a){cancelDuty(a.id);moveActor=undefined;const resume=!!a.resumeIdle;a.duty=false;a.order='ready';if(resume)scheduleResume(a);renderActors();renderZones();zoneEditor();syncSheet();changed();status(a.resumeIdle?'Action annulée. Reprise de l’activité idle.':'Action suspendue; préférence idle conservée.');}return;}if(e.data?.type!=='hero-map-state')return;const a=scene.agents.find(a=>a.id===e.data.agent);if(!a)return;const oldHP=a.hp;for(const key of ['hp','mental','energy'] as const){const v=e.data[key],max=key==='hp'?8:key==='mental'?10:100;if(typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<=max)a[key]=v;}if(a.hp<oldHP)juice.trigger(`hero:${a.id}`,'hit');if(typeof e.data.speed==='number'&&e.data.speed>=1&&e.data.speed<=100)a.speed=e.data.speed;const zone=typeof e.data.zone==='string'&&scene.zones.some(z=>z.id===e.data.zone)?e.data.zone:undefined;if(['ready','watch','patrol'].includes(e.data.order)&&(a.idle?.zone!==zone||e.data.activityChanged)){setDuty(a,e.data.order,zone);}changed();});

 let resourceTime=performance.now();setInterval(()=>{const now=performance.now(),dt=document.hidden?0:Math.min(1,(now-resourceTime)/1000);resourceTime=now;let dirty=false;for(const a of scene.agents){const before=[a.hp,a.mental,a.energy];if(atHQ(a)){a.hp=Math.min(8,a.hp+HQ_RECOVERY_PER_SECOND.hp*dt);a.mental=Math.min(10,a.mental+HQ_RECOVERY_PER_SECOND.mental*dt);a.energy=Math.min(100,a.energy+HQ_RECOVERY_PER_SECOND.energy*dt);}else if(a.duty&&a.order==='watch'&&a.zone&&(!a.journey||a.journey.loopActive)&&a.energy>0)a.energy=Math.max(0,a.energy-WATCH_ENERGY_PER_SECOND*dt);if(before.some((v,i)=>v!==[a.hp,a.mental,a.energy][i])){dirty=true;if(a.id===scene.window.agent&&scene.window.open)$<HTMLIFrameElement>('hero-frame').contentWindow?.postMessage({type:'map-hero-resources',agent:a.id,hp:a.hp,mental:a.mental,energy:a.energy},location.origin);}}dock.refresh();juice.activity();if(dirty)changed();},1000);
 map.on('sourcedata',e=>{if(!e.sourceId||e.sourceId.startsWith('scene-')||e.sourceDataType!=='content')return;for(const a of scene.agents)if(a.duty&&a.order==='ready'&&!a.journey&&!a.point)scheduleDuty(a);});
