 return {buildingPaint:buildings.paint,pointsChanged(){occupants();buildings.pointsChanged();for(const a of scene.agents)if(a.duty&&a.order==='ready'&&!a.journey&&!a.point)scheduleDuty(a);},pointSelected(id?:string){selectedPoint=id;buildings.focusPoint(id);if(id){selectedZone=undefined;zoneEditor();}syncFocus();},centerPoint(id:string){const p=getPoints().find(p=>p.id===id);if(p)centerTarget(`point:${id}`,[p.lng,p.lat]);},pointMoveLabel(){const a=scene.window.open?scene.agents.find(a=>a.id===scene.window.agent):undefined;return a?`Déplacer ${heroRoster.find(h=>h.id===a.hero)!.name} ici`:selectedVehicle?'Déplacer le véhicule ici':undefined;},moveToPoint(id:string){const p=getPoints().find(p=>p.id===id);moveActor=scene.window.open?scene.window.agent:selectedVehicle;if(p)dispatch([p.lng,p.lat],p.name,p.id);},pointClick(id:string){if(juice.select(`point:${id}`))return true;juice.trigger(`point:${id}`,'click');const p=getPoints().find(p=>p.id===id);return p?dispatch([p.lng,p.lat],p.name,p.id):false;},snapshot:()=>structuredClone(scene),effects,active:()=>drawing||!!mode||buildings.picking(),cancelPlacement(){stopDrawing();mode=undefined;moveActor=undefined;scene.window.open=false;selectedVehicle=undefined;windowUI();},replace(next:Scene){stopDrawing();mode=undefined;moveActor=undefined;for(const timer of dutyTimers.values())clearTimeout(timer);dutyTimers.clear();juice.stop();scene=readScene(next);scene.buildings=readBuildings(scene.buildings);scene.juice=readJuice(scene.juice);scene.weather=readWeather(scene.weather);scene.routeStyle=readRouteStyle(scene.routeStyle);scene.zoneColors??={watch:activityForOrder('watch').color,patrol:activityForOrder('patrol').color};$<HTMLInputElement>('zone-color').value=scene.zoneColors.watch;selectedZone=undefined;selectedVehicle=undefined;selectedPoint=undefined;selectedBuilding=undefined;frameKey='';effects();rain.refresh();buildings.refresh();renderActors();renderZones();zoneEditor();vehicleEditor();windowUI();travel.restyle();routeControls();juice.reset();$<HTMLInputElement>('travel-speed').value=String(scene.travelSpeed??8);$('travel-speed-out').textContent=`×${scene.travelSpeed??8}`;for(const a of scene.agents)if(!a.journey){if(a.resumeIdle)scheduleResume(a);else if(a.duty)scheduleDuty(a)};}};
